let actx=null,osc=null;function beep(on){try{if(on&&!osc){actx=actx||new AudioContext();osc=actx.createOscillator();const g=actx.createGain();g.gain.value=.05;osc.type='square';osc.frequency.value=440;osc.connect(g).connect(actx.destination);osc.start();}else if(!on&&osc){osc.stop();osc=null;}}catch(e){}}
